    "LinearityBase",
    inherit = jmvcore::Analysis,
    public = list(
        initialize = function(options, data=NULL, datasetId="", analysisId="", revision=0) {
            super$initialize(
                package = "ReferenceMaterial",
                name = "Linearity",
                version = c(1,0,0),
                options = options,
                results = LinearityResults$new(options=options),
