                revision = revision,
                pause = NULL,
                completeWhenFilled = FALSE,
                requiresMissings = FALSE,
                weightsSupport = 'auto')
        }))

#' Linearity
#'
#' 
#' @param data .
#' @param hs .
#' @param ls .
#' @param l .
#' @param x .
#' @param y .
#' @param prc .
#' @param rc .
#' @param adl .
#' @param m .
#' @param unit .
#' @param ga .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$text} \tab \tab \tab \tab \tab a preformatted \cr
#'   \code{results$abb} \tab \tab \tab \tab \tab a preformatted \cr
#'   \code{results$m} \tab \tab \tab \tab \tab a preformatted \cr
#'   \code{results$mt} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$d$og} \tab \tab \tab \tab \tab a group \cr
#'   \code{results$d$mpx} \tab \tab \tab \tab \tab a preformatted \cr
#'   \code{results$d$dtx} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$d$mpy} \tab \tab \tab \tab \tab a preformatted \cr
#'   \code{results$d$dty} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$r$mpx} \tab \tab \tab \tab \tab a group \cr
#'   \code{results$r$mpy} \tab \tab \tab \tab \tab a group \cr
#'   \code{results$c} \tab \tab \tab \tab \tab a preformatted \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$mt$asDF}
#'
#' \code{as.data.frame(results$mt)}
#'
#' @export
Linearity <- function(
    data,
    hs = 1,
    ls = 0,
    l,
    x,
    y,
    prc,
    rc = list(
                list(l=1, rc=0),
                list(l=2, rc=0.2),
                list(l=3, rc=0.4),
                list(l=4, rc=0.5),
                list(l=5, rc=0.6),
                list(l=6, rc=0.8),
                list(l=7, rc=1)),
    adl = 10,
    m = "HbA1c",
    unit = "%",
    ga = 0.01) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("Linearity requires jmvcore to be installed (restart may be required)")

    if ( ! missing(l)) l <- jmvcore::resolveQuo(jmvcore::enquo(l))
    if ( ! missing(x)) x <- jmvcore::resolveQuo(jmvcore::enquo(x))
    if ( ! missing(y)) y <- jmvcore::resolveQuo(jmvcore::enquo(y))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(l), l, NULL),
            `if`( ! missing(x), x, NULL),
            `if`( ! missing(y), y, NULL))


    options <- LinearityOptions$new(
        hs = hs,
        ls = ls,
        l = l,
        x = x,
        y = y,
        prc = prc,
        rc = rc,
        adl = adl,
        m = m,
        unit = unit,
        ga = ga)

    analysis <- LinearityClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

